item.command:
/bin/zsh -lc "cat > package.json <<'EOF'
{\"name\":\"cowdie\",\"version\":\"1.0.0\",\"private\":true,\"type\":\"module\",\"scripts\":{\"dev\":\"node server.mjs --port 9193\",\"build\":\"node build.mjs\",\"preview\":\"node server.mjs --port 9193 --dist\",\"check\":\"node --check src/main.js && node --check src/scene.js && node --check server.mjs\"}}
EOF
cat > server.mjs <<'EOF'
import http from 'node:http';
import {readFile} from 'node:fs/promises';
import path from 'node:path';
const root=path.resolve(process.argv.includes('--dist')?'dist':'.');
const types={'.html':'text/html','.js':'text/javascript','.css':'text/css','.svg':'image/svg+xml'};
const server=http.createServer(async(req,res)=>{try{let pathname=decodeURIComponent(new URL(req.url,'http://localhost').pathname);let file=path.resolve(root,'.'+(pathname==='/'?'/index.html':pathname));if("'!file.startsWith(root+path.sep)){res.writeHead(403);res.end();return;}const data=await readFile(file);res.writeHead(200,{'"'Content-Type':types[path.extname(file)]||'application/octet-stream'});res.end(data);}catch{res.writeHead(404);res.end('Not found');}});
server.listen(9193,'0.0.0.0',()=>console.log('Cowdie ready on http://localhost:9193'));
EOF
cat > build.mjs <<'EOF'
import {mkdir,copyFile,cp} from 'node:fs/promises';
await mkdir('dist',{recursive:true});await copyFile('index.html','dist/index.html');await cp('src','dist/src',{recursive:true});console.log('Production build created in dist');
EOF
cat > index.html <<'EOF'
<"'!doctype html><html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1"><meta name="theme-color" content="#f7f8f4"><title>GPT-6</title><link rel="stylesheet" href="/src/style.css"></head><body><div id="app"></div><script type="module" src="/src/main.js"></script></body></html>
EOF
cat > src/main.js <<'"'EOF'
import {createScene} from './scene.js';
const icons={home:'<path d=\"m3 10 9-7 9 7v10a1 1 0 0 1-1 1h-5v-7H9v7H4a1 1 0 0 1-1-1Z\"/>',heart:'<path d=\"M20.8 4.6a5.5 5.5 0 0 0-7.8 0L12 5.7l-1.1-1.1a5.5 5.5 0 0 0-7.8 7.8L12 21l8.8-8.6a5.5 5.5 0 0 0 0-7.8Z\"/>',leaf:'<path d=\"M20 3C8 2 2 9 6 15s15 3 14-12Z\"/><path d=\"m3 21 12-12\"/>',spark:'<path d=\"m12 3 2.5 6.5L21 12l-6.5 2.5L12 21l-2.5-6.5L3 12l6.5-2.5Z\"/>',sun:'<circle cx=\"12\" cy=\"12\" r=\"4\"/><path d=\"M12 2v2m0 16v2M2 12h2m16 0h2M5 5l1 1m12 12 1 1M5 19l1-1M18 6l1-1\"/>',moon:'<path d=\"M20 15A9 9 0 0 1 9 3a9 9 0 1 0 11 12Z\"/>',food:'<path d=\"M7 3v7m-3-7v5a3 3 0 0 0 6 0V3M7 11v10M19 3c-4 2-4 9 0 9V3m0 9v9\"/>',ball:'<circle cx=\"12\" cy=\"12\" r=\"9\"/><path d=\"M4 6c6 0 14 8 14 14M6 20c0-6 8-14 14-14\"/>',drop:'<path d=\"M12 3S5 11 5 15a7 7 0 0 0 14 0c0-4-7-12-7-12Z\"/>',sound:'<path d=\"m11 4-6 5H2v6h3l6 5V4Zm4 4a6 6 0 0 1 0 8m3-11a10 10 0 0 1 0 14\"/>',book:'<path d=\"M12 5C8 2 3 3 3 3v16s5-1 9 2c4-3 9-2 9-2V3s-5-1-9 2Zm0 0v16\"/>',gear:'<circle cx=\"12\" cy=\"12\" r=\"4\"/><path d=\"M12 2v3m0 14v3M2 12h3m14 0h3M5 5l2 2m10 10 2 2M5 19l2-2M17 7l2-2\"/>',arrow:'<path d=\"M5 12h14m-5-5 5 5-5 5\"/>',check:'<path d=\"m5 12 4 4L19 6\"/>',gift:'<rect x=\"3\" y=\"8\" width=\"18\" height=\"4\" rx=\"1\"/><path d=\"M5 12v9h14v-9M12 8v13M12 8C2 8 6-2 12 8c6-10 10 0 0 0Z\"/>',close:'<path d=\"m6 6 12 12M6 18 18 6\"/>'};
const icon=(name,cls='')=>"'`<svg class="icon ${cls}" width="21" height="21" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.65" stroke-linecap="round" stroke-linejoin="round">${icons[name]||icons.spark}</svg>`;
let saved;try{saved=JSON.parse(localStorage.getItem('"'cowdie-save'));}catch{}
const state={hunger:64,happiness:86,energy:78,clean:92,xp:35,coins:120,feeds:0,plays:0,washes:0,...saved};
let action='idle',activeTab='feed',selected='apple',sound=false,busy=false,scene;
const foods={apple:{emoji:'🍎',name:'Apple',detail:'A crunchy favorite',gain:18},carrot:{emoji:'🥕',name:'Carrot',detail:'Fresh from the garden',gain:14},berry:{emoji:'🍓',name:'Strawberry',detail:'A little sweet treat',gain:12},hay:{emoji:'🌾',name:'Fresh hay',detail:'Comfort food, cow style',gain:22}};
document.querySelector('#app').innerHTML="'`<aside class="rail"><a class="brand" href="#" aria-label="Home"><span>❋</span></a><nav><button class="rail-button active" data-nav="home" aria-label="Home">${icon('"'home')}</button><button class=\"rail-button\" data-nav=\"journal\" aria-label=\"Pet journal\">"'${icon('"'book')}</button><button class=\"rail-button\" data-nav=\"garden\" aria-label=\"Meadow collection\">"'${icon('"'leaf')}</button></nav><div class=\"rail-bottom\"><button class=\"rail-button\" data-nav=\"settings\" aria-label=\"Settings\">"'${icon('"'gear')}</button><div class=\"avatar\">J<span></span></div></div></aside>
<main><header><div class=\"wordmark\"><h1>GPT-6</h1><span class=\"beta\">a little love, every day</span></div><div class=\"header-right\"><span class=\"day-tag\">"'${icon('"'sun')} A lovely day to be here</span><div class=\"coins\"><span>✦</span> <b id=\"coins\">120</b></div><button class=\"sound-button\" id=\"sound\" aria-label=\"Enable sound\">"'${icon('"'sound')}<span class=\"sound-slash\"></span></button></div></header>
<div class=\"page-heading\"><div><div class=\"eyebrow\">YOUR LITTLE HAPPY PLACE</div><h2>Hey, friend. <span>Meet Cowdie.</span> <span class=\"wave\">✳</span></h2><p>A little care. A lot of love. A friend that’s always happy to see you.</p></div><div class=\"streak\">"'${icon('"'sun')}<div><strong>Day 1 together</strong><span>The start of something sweet</span></div></div></div>
<div class=\"main-grid\"><section class=\"habitat\" aria-label=\"Cowdie's interactive 3D meadow\"><div class=\"scene-top\"><div class=\"location\"><span class=\"green-dot\"></span> The cozy meadow "'${icon('"'leaf')}</div><button id=\"daynight\" class=\"weather\" aria-label=\"Toggle day and night\">"'${icon('"'sun')} <span>Sunny & peaceful</span></button></div><div class=\"cloud cloud-one\"></div><div class=\"cloud cloud-two\"></div><div class=\"scene-message\" id=\"speech\">Life is better with moo. <span>♡</span></div><canvas id=\"world\" aria-label=\"Cowdie the 3D cow. Click to pet.\" role=\"button\" tabindex=\"0\"></canvas><div id=\"particles\" aria-hidden=\"true\"></div><div class=\"pet-caption\"><span class=\"pet-name\">Cowdie <span>♀</span></span><span class=\"mood\"><i></i> <span id=\"mood\">Feeling pretty moo-velous</span></span></div><div class=\"scene-bottom\"><span>"'${icon('"'heart')} Click Cowdie for a little love</span><button id=\"rotate\" aria-label=\"Rotate the meadow\">↻ <span>Look around</span></button></div></section>
<aside class=\"care-panel\"><div class=\"panel-title\"><h3>A happy little soul</h3><span class=\"live-dot\"></span></div><p class=\"muted\">Looking good, feeling good.</p><div class=\"stats\">"'${[['"'hunger','food','Fullness','sage'],['happiness','heart','Happiness','pink'],['energy','sun','Energy','yellow'],['clean','drop','Cleanliness','blue']].map(([key,i,label,color])=>"'`<div class="stat ${color}"><div class="stat-line"><span>${icon(i)} ${label}</span><b id="${key}-value">${state[key]}<small>/100</small></b></div><div class="bar"><div id="${key}-bar" style="width:${state[key]}%"></div></div></div>`).join('"'')}</div><div class=\"divider\"></div><div class=\"friendship\"><div class=\"level-icon\">"'${icon('"'leaf')}</div><div><h4>Little beginnings</h4><span id=\"level-label\">Level 1 · Growing together</span></div><span class=\"level-number\" id=\"level-number\">01</span></div><div class=\"xp-heading\"><span>Next friendship level</span><b id=\"xp-label\">35 / 100 XP</b></div><div class=\"bar xp\"><div id=\"xp-bar\"></div></div><div class=\"tip\">"'${icon('"'spark')}<p>It’s the little things.<br>Every bit of care brings you closer.</p></div></aside></div>
<div class=\"bottom-grid\"><section class=\"interaction-card\"><div class=\"tabs\" role=\"tablist\">"'${[['"'feed','food','Feed'],['play','ball','Play'],['wash','drop','Wash'],['rest','moon','Rest']].map(([key,i,label])=>"'`<button role="tab" aria-selected="${key==='"'feed'}\" class=\"tab "'${key==='"'feed'?'active':''}\" data-tab=\""'${key}">${icon(i)} ${label}</button>`).join('"'')}<span class=\"tray-label\">A LITTLE TLC GOES A LONG WAY</span></div><div id=\"tray\"></div></section><section class=\"daily-card\"><div class=\"daily-title\"><span class=\"daily-symbol\">"'${icon('"'sun')}</span><h3>Little moments, big love</h3></div><p>A few good things to do together.</p><div id=\"tasks\"></div><div class=\"daily-footer\">"'${icon('"'gift')} <span>A happy pet is its own reward.</span> ♡</div></section></div><footer><span>A tiny world. A real connection.</span><span>Made for the little moments <span class=\"footer-flower\">✳</span></span></footer></main><dialog id=\"modal\"><button id=\"close-modal\" aria-label=\"Close\">"'${icon('"'close')}</button><div id=\"modal-content\"></div></dialog><div id=\"toast\" role=\"status\"></div>"'`;
function save(){try{localStorage.setItem('"'cowdie-save',JSON.stringify(state));}catch{}}
function update(){for(const key of ['hunger','happiness','energy','clean']){state[key]=Math.max(0,Math.min(100,state[key]));document.getElementById(key+'-value').innerHTML="'`${Math.round(state[key])}<small>/100</small>`;document.getElementById(key+'"'-bar').style.width=state[key]+'%';}document.querySelector('#coins').textContent=state.coins;const level=1+Math.floor(state.xp/100);document.querySelector('#level-label').textContent="'`Level ${level} · Growing together`;document.querySelector('"'#level-number').textContent=String(level).padStart(2,'0');document.querySelector('#xp-label').textContent="'`${state.xp%100} / 100 XP`;document.querySelector('"'#xp-bar').style.width=state.xp%100+'%';document.querySelector('#tasks').innerHTML=[['feeds','A tasty little snack'],['plays','A moment of play'],['washes','Freshen up together']].map(([key,label])=>"'`<div class="task ${state[key]?'"'done':''}\"><span class=\"checkbox\">"'${state[key]?icon('"'check'):''}</span><span>"'${label}</span><span>${state[key]?'"'Done':'+10 XP'}</span></div>"'`).join('"'');save();}
function renderTray(){const el=document.querySelector('#tray');if(activeTab==='feed'){el.innerHTML="'`<div class="tray-intro"><h3>Something yummy?</h3><p>Pick a snack. Make their day.</p></div><div class="food-options">${Object.entries(foods).map(([k,f])=>`<button class="food ${selected===k?'"'selected':''}\" data-food=\""'${k}" aria-pressed="${selected===k}"><span class="food-emoji">${f.emoji}</span><strong>${f.name}</strong><span>+${f.gain} fullness</span>${selected===k?'"'<i>✓</i>':''}</button>"'`).join('"'')}</div><div class=\"feed-row\"><span>"'${icon('"'leaf')} Fresh snacks, full hearts.</span><button class=\"primary\" id=\"do-action\" "'${busy?'"'disabled':''}>Feed Cowdie "'${icon('"'arrow')}</button></div>"'`;el.querySelectorAll('"'[data-food]').forEach(b=>b.onclick=()=>{selected=b.dataset.food;renderTray();});}else{const data={play:['Let’s make some memories.','A happy little bounce is all it takes.','🎾','Play together'],wash:['Fresh as a daisy.','A gentle bubble bath for your little friend.','🫧','Give a bubble bath'],rest:['Time for a little daydream.','A peaceful nap to recharge those tiny hooves.','🌙','Tuck Cowdie in']}[activeTab];el.innerHTML="'`<div class="other-care"><span class="care-emoji">${data[2]}</span><div><h3>${data[0]}</h3><p>${data[1]}</p><button class="primary" id="do-action" ${busy?'"'disabled':''}>"'${data[3]} ${icon('"'arrow')}</button></div></div>"'`;}document.querySelector('"'#do-action').onclick=perform;}
let toastTimer;function toast(t){const e=document.querySelector('#toast');e.textContent=t;e.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>e.classList.remove('show'),3200);}
function particles(char){const parent=document.querySelector('#particles');for(let i=0;i<7;i++){const p=document.createElement('span');p.textContent=char;p.style.cssText="'`left:${43+Math.random()*18}%;top:${39+Math.random()*18}%;--x:${(Math.random()-.5)*160}px;animation-delay:${i*.09}s`;parent.append(p);setTimeout(()=>p.remove(),2200);}}
function chime(){if(!sound)return;try{const ctx=new AudioContext();[523,659,784].forEach((f,i)=>{const o=ctx.createOscillator(),g=ctx.createGain();o.connect(g);g.connect(ctx.destination);o.frequency.value=f;g.gain.setValueAtTime(.045,ctx.currentTime+i*.1);g.gain.exponentialRampToValueAtTime(.001,ctx.currentTime+i*.1+.28);o.start(ctx.currentTime+i*.1);o.stop(ctx.currentTime+i*.1+.3);});setTimeout(()=>ctx.close(),900);}catch{}}
function perform(){if(busy)return;busy=true;action=activeTab;scene?.setAction(action,foods[selected].emoji);const text={feed:'"'Nom nom… you know me so well"'! ♡'"',play:'Best. Day. Ever"'! ✨'"',wash:'Bubbles make everything better"'! 🫧'"',rest:'Just five moo-re minutes… z z z'};document.querySelector('#speech').textContent=text[action];document.querySelector('#mood').textContent={feed:'Enjoying something delicious',play:'Having a bouncing good time',wash:'Feeling squeaky clean',rest:'Dreaming of greener pastures'}[action];if(action==='feed'){state.hunger+=foods[selected].gain;state.happiness+=4;state.feeds++;}if(action==='play'){state.happiness+=18;state.energy-=8;state.plays++;}if(action==='wash'){state.clean+=25;state.happiness+=5;state.washes++;}if(action==='rest')state.energy+=25;state.xp+=10;state.coins+=5;particles({feed:'♥',play:'✦',wash:'◯',rest:'z'}[action]);chime();update();renderTray();setTimeout(()=>{busy=false;action='idle';scene?.setAction('idle');document.querySelector('#speech').innerHTML='That was lovely. You’re my favorite. <span>♡</span>';document.querySelector('#mood').textContent='Feeling loved & lovely';renderTray();toast('+10 friendship XP · A little closer together');},3600);}
document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{activeTab=b.dataset.tab;document.querySelectorAll('[data-tab]').forEach(t=>{t.classList.toggle('active',t===b);t.setAttribute('aria-selected',String(t===b));});renderTray();});
function pet(){if(busy)return;particles('♥');scene?.setAction('pet');state.happiness+=2;update();document.querySelector('#speech').textContent='A little head scratch? Yes, please"'! ♡'"';chime();setTimeout(()=>scene?.setAction('idle'),1300);}
const canvas=document.querySelector('#world');canvas.onclick=pet;canvas.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();pet();}};let night=false;document.querySelector('#daynight').onclick=()=>{night="'!night;document.querySelector('"'.habitat').classList.toggle('night',night);document.querySelector('#daynight').innerHTML=icon(night?'moon':'sun')+"'`<span>${night?'"'Moonlit & mellow':'Sunny & peaceful'}</span>"'`;scene?.setNight(night);};document.querySelector('"'#rotate').onclick=()=>scene?.rotate();document.querySelector('#sound').onclick=()=>{sound="'!sound;document.querySelector('"'#sound').classList.toggle('enabled',sound);document.querySelector('#sound').setAttribute('aria-label',sound?'Mute sound':'Enable sound');toast(sound?'Little sounds are on':'Sounds are off');chime();};
const modal=document.querySelector('#modal');document.querySelector('#close-modal').onclick=()=>modal.close();modal.onclick=e=>{if(e.target===modal)modal.close();};document.querySelectorAll('[data-nav]').forEach(b=>b.onclick=()=>{const n=b.dataset.nav;if(n==='home'){modal.close();return;}document.querySelector('#modal-content').innerHTML=n==='journal'?"'`<div class="modal-emoji">📖</div><h2>Our little story</h2><p>Every moment with Cowdie counts.</p><div class="journal-stats"><div><b>${state.feeds}</b>snacks shared</div><div><b>${state.plays}</b>play dates</div><div><b>${state.washes}</b>bubble baths</div></div><div class="journal-note">Day 1 · You found a new forever friend.<br>Here’s to many more moo-ments together. ♡</div>`:n==='"'garden'?"'`<div class="modal-emoji">🌱</div><h2>Your growing meadow</h2><p>Friendship makes your little world bloom.</p><div class="collection"><div>🌼<strong>Daisy patch</strong><span>At home in your meadow</span></div><div>🍄<strong>Little mushrooms</strong><span>At home in your meadow</span></div><div>🌳<strong>Friendship tree</strong><span>${state.xp>=100?'"'Unlocked"'! Keep growing together.'"':"'`${100-state.xp} XP until level 2`}</span></div></div>`:`<div class="modal-emoji">☀️</div><h2>Your cozy corner</h2><p>Make yourself at home.</p><button class="setting" id="setting-sound">Little sounds <span>${sound?'"'On':'Off'} →</span></button><button class=\"setting\" id=\"setting-time\">Meadow lighting <span>"'${night?'"'Moonlight':'Sunshine'} →</span></button><p class=\"save-note\">Your friendship is saved automatically on this device.</p>"'`;modal.showModal();document.querySelector('"'#setting-sound')?.addEventListener('click',()=>{document.querySelector('#sound').click();modal.close();});document.querySelector('#setting-time')?.addEventListener('click',()=>{document.querySelector('#daynight').click();modal.close();});});
update();renderTray();try{scene=createScene(canvas);}catch(e){canvas.style.display='none';document.querySelector('.habitat').insertAdjacentHTML('beforeend','<div class=\"fallback-cow\" role=\"button\" tabindex=\"0\" aria-label=\"Pet Cowdie\">🐮</div>');document.querySelector('.fallback-cow').onclick=pet;console.warn('3D unavailable',e);}
setInterval(()=>{if("'!busy){state.hunger-=1;state.energy-=.5;state.clean-=.3;update();}},60000);
EOF'

